# (P, Q, W0, W1) for W_j = P W_{j-1} - Q W_{j-2}; used to check the Horadam
# results of the paper on generators other than the alternating-sign Lucas one
HORADAM_CASES = {
    "alternating Lucas": (-1, -1, -2, 1),
    "Lucas": (1, -1, 2, 1),
    "Fibonacci": (1, -1, 0, 1),
    "alternating Fibonacci": (-1, -1, 0, 1),
    "Pell": (2, -1, 0, 1),
    "Pell-Lucas": (2, -1, 2, 2),
    "Jacobsthal": (1, -2, 0, 1),
    "complex roots (1,1)": (1, 1, 2, -1),
    "complex roots (2,5)": (2, 5, 1, 1),
    "repeated root 2": (4, 4, 1, 3),
    "repeated root -3": (-6, 9, 2, -1),
    "random integers": (-2, 5, 3, 1),
}


# ---------------------------------------------------------------------------
# FFT ("spectral") algorithm, valid for any real generator
# ---------------------------------------------------------------------------

def sing_tol(lam):
    return 100 * EPS * max(1.0, float(np.max(np.abs(lam))))


def fft_slogdet(g):
    lam = fourier_eigs(g)
    if np.min(np.abs(lam)) <= sing_tol(lam):
        return 0.0, -np.inf
    q = (len(g) - 1) // 2
    phase = (-1) ** q * np.exp(1j * np.sum(np.angle(lam)))
    if abs(phase.imag) > 1e-8:
        raise FloatingPointError("determinant phase is not real")
    return (1.0 if phase.real >= 0 else -1.0), float(np.sum(np.log(np.abs(lam))))


def fft_inverse_generator(g):
    lam = fourier_eigs(g)
    if np.min(np.abs(lam)) <= sing_tol(lam):
        raise np.linalg.LinAlgError("singular matrix")
    n = len(g)
    d = np.fft.fft(1.0 / lam) / n          # generator of C_n(g)^{-1}
    h = d[(-np.arange(n)) % n]              # ... times Delta_n gives h_r = d_{-r}
    return np.real_if_close(h, tol=1000).astype(float)


def fft_inverse(g):
    return left_circ(fft_inverse_generator(g))


def fft_spectrum(g):
    # complete real spectrum: lambda_0, lambda_{n/2} (n even) and the pairs
    # +-|lambda_k| for the remaining modes
    lam = fourier_eigs(g)
    n = len(g)
    mods = np.abs(lam[1:(n - 1) // 2 + 1])
    parts = [lam[:1].real, mods, -mods]
    if n % 2 == 0:
        parts.append(lam[n // 2:n // 2 + 1].real)
    return np.sort(np.concatenate(parts))


def scipy_inverse(g):
    # structured baseline that does not use our formulas: solve C_n x = I with
    # scipy's circulant solver, then permute columns (LC^{-1} = C^{-1} Delta_n)
    n = len(g)
    perm = np.r_[0, n - 1:0:-1]
    return sla.solve_circulant(g[perm], np.eye(n))[:, perm]


# ---------------------------------------------------------------------------
# Horadam closed forms
# ---------------------------------------------------------------------------

def horadam(n, P, Q, W0, W1):
    W = [W0, W1]
    while len(W) < n + 1:
        W.append(P * W[-1] - Q * W[-2])
    return W[:n + 1]


def horadam_ab(n, P, Q, W0, W1):
    """a_n, b_n and the denominator 1 - V_n + Q^n."""
    W = horadam(n, P, Q, W0, W1)
    V_n = horadam(n, P, Q, 2, P)[n]
    return W0 - W[n], W1 - P * W0 + Q * W[n - 1], 1 - V_n + Q ** n


def horadam_det(n, P, Q, W0, W1):
    # closed-form determinant for Horadam generators; None when a
    # characteristic root is an n-th root of unity
    a, b, den = horadam_ab(n, P, Q, W0, W1)
    if den == 0:
        return None
    return Fraction((-1) ** ((n - 1) // 2) * (a ** n - (-b) ** n), den)


def horadam_inv_generator(n, P, Q, W0, W1):
    # explicit inverse: h_r = c_{-r} - P c_{-r-1} + Q c_{-r-2}
    a, b, den = horadam_ab(n, P, Q, W0, W1)
    D = a ** n - (-b) ** n
    if den == 0 or D == 0:
        return None
    c = [Fraction((-b) ** j * a ** (n - 1 - j), D) for j in range(n)]
    gen = [c[j] - P * c[(j - 1) % n] + Q * c[(j - 2) % n] for j in range(n)]
    return [gen[(-r) % n] for r in range(n)]


def check_horadam(max_n=12):
    rows = []
    for name, (P, Q, W0, W1) in HORADAM_CASES.items():
        for n in range(2, max_n + 1):
            row = dict(case=name, P=P, Q=Q, W0=W0, W1=W1, n=n)
            a, b, den = horadam_ab(n, P, Q, W0, W1)
            if den == 0:
                rows.append({**row, "degenerate": True})
                continue
            W = horadam(n, P, Q, W0, W1)[:n]
            M = sp.Matrix(n, n, lambda i, j: W[(i + j) % n])
            det = M.det(method="bareiss")

            z = np.exp(2j * np.pi * np.arange(n) / n)
            lam = fourier_eigs(np.array(W, dtype=float))
            lam_formula = (a + b * z) / (1 - P * z + Q * z * z)
            eig_err = np.max(np.abs(lam - lam_formula)) / max(1.0, np.max(np.abs(lam)))

            h = horadam_inv_generator(n, P, Q, W0, W1)
            inv_ok = None
            if h is not None:
                H = sp.Matrix(n, n, lambda i, j: sp.Rational(h[(i + j) % n].numerator,
                                                            h[(i + j) % n].denominator))
                inv_ok = bool(M * H == sp.eye(n))

            # singularity criterion for Horadam generators
            criterion = (a + b == 0) or (n % 2 == 0 and a == b)
            rows.append({**row, "degenerate": False, "det_exact": str(det),
                         "det_closed_form_matches": bool(det == horadam_det(n, P, Q, W0, W1)),
                         "eigenvalue_formula_max_rel_error": float(eig_err),
                         "singular": bool(det == 0),
                         "singularity_criterion_matches": bool(criterion == (det == 0)),
                         "explicit_inverse_matches": inv_ok})
    return pd.DataFrame(rows)


# ---------------------------------------------------------------------------
# closed forms for the alternating-sign Lucas case
# ---------------------------------------------------------------------------

def det_closed(n):
    """Explicit determinant (P = Q = -1, W0 = -2, W1 = 1), exact integer."""
    d = horadam_det(n, -1, -1, -2, 1)
    assert d.denominator == 1
    return int(d)


def closed_slogdet(n):
    # O(1) evaluation of the explicit determinant. Writing a = -s alpha^n A,
    # b = s alpha^{n-1} B, 1+s-sL_n = -s alpha^n D (A, B, D -> 1) gives
    # log|det| = n(n-1) log alpha + n log A + log(1 - r^n) - log D, r = B/(alpha A),
    # and the sign is (-1)^{q_n+1} for n >= 3, n != 4.
    if n == 4:
        return 0.0, -np.inf
    if n < 3:
        d = det_closed(n)
        return float(np.sign(d)), math.log(abs(d))
    s = 1 if n % 2 == 0 else -1
    rho = (1 - ALPHA) / ALPHA
    A = 1 + rho ** n - 2 * s * ALPHA ** -n
    B = 1 + rho ** (n - 1) + s * ALPHA ** -(n - 1)
    D = 1 + rho ** n - (1 + s) * s * ALPHA ** -n
    r = B / (ALPHA * A)
    logdet = (n * (n - 1) * math.log(ALPHA) + n * math.log(A)
              + math.log(-math.expm1(n * math.log(r))) - math.log(D))
    return float((-1) ** ((n - 1) // 2 + 1)), logdet


def kappa_formula(n):
    """Exact kappa_2 from the condition-number theorem, else NaN.

    The theorem states the even case for n >= 6 and the odd case for n >= 13.
    The odd formula also holds at n = 11 by direct computation, which is why
    the odd branch starts there; at n = 3, 5, 7, 9 the smallest |lambda_k| is not
    at k = 0 and the formula does not apply.
    """
    if n % 2 == 0 and n >= 6:
        return (lucas(n + 1) - 1) / (lucas(n - 2) - 3)
    if n % 2 == 1 and n >= 11:
        a, b, d = 2 + lucas(n), 1 - lucas(n - 1), lucas(n - 2) + 3
        c = math.cos(math.pi / n)
        a2b2 = float(Fraction(a * a + b * b, d * d))      # scaled to avoid overflow
        ab = float(Fraction(a * b, d * d))
        return math.sqrt((a2b2 - 2 * ab * c) / (5 - 4 * c * c))
    return float("nan")


def kappa_rate(n):
    if n % 2 == 0:
        return ALPHA ** 3 + (5 + 3 * math.sqrt(5)) * ALPHA ** (2.0 - n)
    return ALPHA ** 3 - ALPHA ** 6 * math.pi ** 2 / (2 * n * n)


# ---------------------------------------------------------------------------
# timing
# ---------------------------------------------------------------------------

def time_it(f, repeats, warmup, batch_seconds):
    for _ in range(warmup):
        f()
    t0 = time.perf_counter()
    f()
    once = max(time.perf_counter() - t0, EPS)
    batch = max(1, min(100_000, int(np.ceil(batch_seconds / once))))

    samples = np.empty(repeats)
    gc_was_on = gc.isenabled()
    gc.disable()
    try:
        for k in range(repeats):
            t0 = time.perf_counter_ns()
            for _ in range(batch):
                f()
            samples[k] = (time.perf_counter_ns() - t0) * 1e-9 / batch
    finally:
        if gc_was_on:
            gc.enable()

    q1, med, q3 = np.quantile(samples, [0.25, 0.5, 0.75])
    return dict(median=med, q1=q1, q3=q3, mean=samples.mean(),
                std=samples.std(ddof=1), min=samples.min(), batch_size=float(batch))


def bench_one(n, repeats, warmup, batch_seconds):
    # matrix and generator are built once, outside the timed region
    g = alt_lucas_float(n)
    A = left_circ(g)
    kernels = {
        "det_standard": lambda: np.linalg.slogdet(A),
        "det_spectral": lambda: fft_slogdet(g),
        "det_closed": lambda: closed_slogdet(n),
        "inv_standard": lambda: np.linalg.inv(A),
        "inv_scipy_circulant": lambda: scipy_inverse(g),
        "inv_spectral": lambda: fft_inverse(g),
        "inv_generator": lambda: fft_inverse_generator(g),
        "eig_standard": lambda: np.linalg.eigvalsh(A),
        "eig_spectral": lambda: fft_spectrum(g),
    }
    # rotate the order with n so no kernel always runs first on a cold cache
    names = list(kernels)
    k = n % len(names)
    names = names[k:] + names[:k]

    row = {"n": float(n)}
    for name in names:
        for key, val in time_it(kernels[name], repeats, warmup, batch_seconds).items():
            row[f"{name}_{key}"] = float(val)

    t = lambda name: row[f"{name}_median"]
    row["det_speedup"] = t("det_standard") / t("det_spectral")
    row["det_closed_speedup"] = t("det_standard") / t("det_closed")
    row["det_closed_vs_fft"] = t("det_spectral") / t("det_closed")
    row["inv_scipy_speedup"] = t("inv_standard") / t("inv_scipy_circulant")
    row["inv_spectral_vs_scipy"] = t("inv_scipy_circulant") / t("inv_spectral")
    row["inv_speedup"] = t("inv_standard") / t("inv_spectral")
    row["eig_speedup"] = t("eig_standard") / t("eig_spectral")
    row["generator_speedup_vs_dense"] = t("inv_standard") / t("inv_generator")
    return row


# ---------------------------------------------------------------------------
# accuracy, exact determinants, condition numbers
# ---------------------------------------------------------------------------

def exact_log(value):
    with mp.workprec(200):
        return mp.log(abs(mp.mpf(value)))


def rel_to(x, ref):
    return float(abs(mp.mpf(x) - ref) / abs(ref))


def scaled_rel_error(x, ref):
    # both scaled by max|ref| first: the inverse has entries near alpha^{-n},
    # and squaring them in the norm would underflow otherwise
    s = np.max(np.abs(ref))
    return float(np.linalg.norm((x - ref) / s) / np.linalg.norm(ref / s))


def accuracy_one(n):
    g = alt_lucas_float(n)
    A = left_circ(g)
    sd, ld = np.linalg.slogdet(A)
    sf, lf = fft_slogdet(g)
    sc, lc = closed_slogdet(n)
    row = dict(n=n, singular=bool(sd == 0 or sf == 0), det_sign_dense=float(sd),
               det_sign_spectral=float(sf), logabsdet_dense=float(ld), logabsdet_spectral=float(lf))
    if row["singular"]:
        return row

    row["logabsdet_abs_error"] = abs(lf - ld)
    row["logabsdet_rel_error"] = abs(lf - ld) / max(abs(ld), 1.0)
    ref = exact_log(det_closed(n))
    row["logabsdet_rel_error_exact_dense"] = rel_to(ld, ref)
    row["logabsdet_rel_error_exact_fft"] = rel_to(lf, ref)
    row["logabsdet_rel_error_exact_closed"] = rel_to(lc, ref)
    row["det_sign_closed"] = sc

    X_dense = np.linalg.inv(A)
    X_fft = fft_inverse(g)
    row["inverse_rel_fro_error"] = scaled_rel_error(X_fft, X_dense)
    row["inverse_residual_inf"] = float(np.linalg.norm(A @ X_fft - np.eye(n), np.inf))
    # share of subnormal numbers in the dense inverse -- this is what makes
    # numpy.linalg.inv jump between n=500 and n=1000 (see 03_subnormal_check.py)
    tiny = np.finfo(float).tiny
    row["inverse_subnormal_fraction"] = float(np.mean((np.abs(X_dense) < tiny) & (X_dense != 0)))

    mu_dense = np.linalg.eigvalsh(A)
    mu_fft = fft_spectrum(g)
    row["spectrum_rel_l2_error"] = scaled_rel_error(mu_fft, mu_dense)
    row["spectrum_max_abs_error"] = float(np.max(np.abs(mu_fft - mu_dense)))
    return row


def bareiss_det(n):
    g = alt_lucas(n)
    return int(sp.Matrix(n, n, lambda i, j: g[(i + j) % n]).det(method="bareiss"))


def sci(value, digits=8):
    if value == 0:
        return "0"
    with localcontext() as ctx:
        ctx.prec = digits + 8
        return f"{Decimal(value):.{digits - 1}E}"


def high_prec_product(n, exact):
    # first-submission check, kept as an independent confirmation:
    # (-1)^{q_n} prod_k lambda_k in high precision, rounded to an integer
    g = alt_lucas(n)
    with mp.workdps(max(100, len(str(abs(exact))) + 60)):
        w = mp.exp(2j * mp.pi / n)
        lam = [mp.fsum(g[j] * w ** (j * k) for j in range(n)) for k in range(n)]
        val = (-1) ** ((n - 1) // 2) * mp.fprod(lam)
        # the product is real for a real generator; a visible imaginary part
        # would mean the precision was too low
        if abs(mp.im(val)) > mp.mpf("1e-6") * max(1, abs(val)):
            raise FloatingPointError(f"product not real at n={n}")
        return int(mp.nint(mp.re(val))) == exact


def det_check_one(n):
    exact = bareiss_det(n)
    g = alt_lucas_float(n)
    sd, ld = np.linalg.slogdet(left_circ(g))
    sf, lf = fft_slogdet(g)
    sc, lc = closed_slogdet(n)
    row = dict(n=n, singular=exact == 0, exact_determinant=str(exact), exact_scientific=sci(exact),
               closed_form_matches_bareiss=det_closed(n) == exact,
               signs_agree=bool(np.sign(exact) == sd == sf == sc))
    if exact != 0:
        ref = exact_log(exact)
        row.update(logdet_rel_error_dense=rel_to(ld, ref), logdet_rel_error_fft=rel_to(lf, ref),
                   logdet_rel_error_closed=rel_to(lc, ref))
    row["high_precision_spectral_integer_match"] = (
        high_prec_product(n, exact) if n in HIGH_PREC_ORDERS else None)
    return row


def condition_one(n):
    g = alt_lucas_float(n)
    mu = fft_spectrum(g)
    singular = bool(np.min(np.abs(mu)) <= sing_tol(mu))
    kappa = np.nan if singular else float(np.max(np.abs(mu)) / np.min(np.abs(mu)))
    diff = kappa - ALPHA ** 3
    mods = np.abs(fourier_eigs(g))
    return dict(n=n, parity="even" if n % 2 == 0 else "odd", singular=singular, kappa2=kappa,
                difference_from_alpha3=diff, absolute_difference_from_alpha3=abs(diff),
                kappa2_exact_formula=kappa_formula(n),
                kappa2_leading_order_prediction=kappa_rate(n),
                argmin_k=int(np.argmin(mods)), argmax_k=int(np.argmax(mods)),
                n2_times_alpha3_minus_kappa=n * n * (ALPHA ** 3 - kappa) if n % 2 else np.nan)


# ---------------------------------------------------------------------------
# quick self-test before the long runs
# ---------------------------------------------------------------------------

def self_test():
    for n in (3, 5, 10):
        g = alt_lucas_float(n)
        A = left_circ(g)
        assert np.allclose(A, reversal(n) @ circ(g)), "factorization"
        sd, ld = np.linalg.slogdet(A)
        sf, lf = fft_slogdet(g)
        assert sd == sf and np.isclose(ld, lf, rtol=1e-12), "determinant"
        assert np.linalg.norm(A @ fft_inverse(g) - np.eye(n), np.inf) < 1e-10, "inverse"
        assert np.allclose(fft_spectrum(g), np.linalg.eigvalsh(A), rtol=1e-11, atol=1e-11), "spectrum"
        assert np.allclose(scipy_inverse(g), np.linalg.inv(A), rtol=1e-10, atol=1e-12), "scipy baseline"
        assert det_closed(n) == bareiss_det(n), "closed-form determinant"


# ---------------------------------------------------------------------------
# driver
# ---------------------------------------------------------------------------

def run_benchmark(sizes, repeats, warmup, batch_seconds, sessions, out):
    if threadpool_limits is not None:
        threadpool_limits(limits=1)

    # the whole sweep is repeated; a slow phase of the machine then spoils one
    # session instead of one kernel, and the median over sessions is reported
    rows = []
    for s in range(sessions):
        for n in sizes:
            print(f"session {s + 1}/{sessions}, n = {n}", flush=True)
            rows.append({**bench_one(n, repeats, warmup, batch_seconds), "session": s})
    per_session = pd.DataFrame(rows)
    per_session.to_csv(out / "timing_sessions.csv", index=False)
    timing = per_session.drop(columns="session").groupby("n", as_index=False).median()
    accuracy = pd.DataFrame([accuracy_one(n) for n in sizes])
    timing.to_csv(out / "timing_results.csv", index=False)
    accuracy.to_csv(out / "accuracy_results.csv", index=False)

    blas = "threadpoolctl not installed"
    if threadpool_info is not None:
        blas = [{k: lib.get(k) for k in ("internal_api", "version", "architecture", "num_threads")}
                for lib in threadpool_info()]
    meta = {
        "timestamp_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "python": sys.version.split()[0], "numpy": np.__version__, "scipy": scipy.__version__,
        "pandas": pd.__version__, "sympy": sp.__version__, "blas": blas,
        "platform": platform.platform(), "processor": platform.processor(),
        "threads": {v: os.environ.get(v) for v in
                    ("OMP_NUM_THREADS", "OPENBLAS_NUM_THREADS", "MKL_NUM_THREADS", "NUMEXPR_NUM_THREADS")},
        "sizes": list(sizes), "sessions": sessions, "repeats": repeats, "warmup": warmup,
        "target_batch_seconds": batch_seconds, "statistic": "median over sessions of per-session medians",
        "matrix_assembly_included_in_timing": False,
    }
    (out / "benchmark_metadata.json").write_text(json.dumps(meta, indent=2))
    return timing, accuracy, meta


def reuse(src, out):
    for name in ("timing_results.csv", "accuracy_results.csv", "benchmark_metadata.json"):
        if not (src / name).exists():
            raise FileNotFoundError(f"{src / name} not found")
        shutil.copy2(src / name, out / name)
    if (src / "timing_sessions.csv").exists():
        shutil.copy2(src / "timing_sessions.csv", out / "timing_sessions.csv")
    return (pd.read_csv(out / "timing_results.csv"), pd.read_csv(out / "accuracy_results.csv"),
            json.loads((out / "benchmark_metadata.json").read_text()))


def write_tables(timing, accuracy, meta, source, out):
    det = pd.DataFrame([det_check_one(n) for n in DET_ORDERS])
    assert det["closed_form_matches_bareiss"].all(), "closed form disagrees with Bareiss"

    hor = check_horadam()
    hor.to_csv(out / "horadam_validation.csv", index=False)
    ok = hor[~hor["degenerate"]]
    assert ok["det_closed_form_matches"].all() and ok["singularity_criterion_matches"].all()
    assert ok["explicit_inverse_matches"].dropna().all()
    assert (ok["eigenvalue_formula_max_rel_error"] < 1e-9).all()

    cond = pd.DataFrame([condition_one(n) for n in sorted(set(COND_EVEN + COND_ODD))])

    # one CSV per table / figure of the paper
    timing[["n", "det_standard_median", "det_spectral_median", "det_closed_median",
            "eig_standard_median", "eig_spectral_median"]].to_csv(out / "table_runtime.csv", index=False)
    timing[["n", "inv_standard_median", "inv_scipy_circulant_median", "inv_spectral_median",
            "inv_generator_median"]].to_csv(out / "table_runtime_inverse.csv", index=False)
    accuracy[["n", "logabsdet_rel_error_exact_dense", "logabsdet_rel_error_exact_fft",
              "logabsdet_rel_error_exact_closed", "inverse_rel_fro_error", "inverse_residual_inf",
              "spectrum_rel_l2_error", "inverse_subnormal_fraction"]].to_csv(out / "table_accuracy.csv", index=False)
    det[det["n"].isin(DET_TABLE_ORDERS)].to_csv(out / "table_determinant_validation.csv", index=False)
    timing[["n", "det_speedup", "det_closed_speedup", "inv_speedup", "inv_scipy_speedup",
            "eig_speedup"]].to_csv(out / "figure_speedup.csv", index=False)
    timing[["n", "inv_standard_median", "inv_scipy_circulant_median", "inv_spectral_median",
            "inv_generator_median", "generator_speedup_vs_dense"]].to_csv(
        out / "figure_inverse_representations.csv", index=False)
    cond.to_csv(out / "figure_condition_deviation.csv", index=False)

    # full data next to the extracts
    det.to_csv(out / "determinant_validation_results.csv", index=False)
    cond.to_csv(out / "condition_number_results.csv", index=False)

    (out / "publication_metadata.json").write_text(json.dumps({
        "timing_source": source, "timing_metadata": meta,
        "generated_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "exact_checks": {
            "sympy": sp.__version__, "mpmath": mp.__version__,
            "closed_form_vs_bareiss": [min(DET_ORDERS), max(DET_ORDERS)],
            "high_precision_product": list(HIGH_PREC_ORDERS),
            "horadam_cases": list(HORADAM_CASES),
        },
    }, indent=2))


def main():
    ap = argparse.ArgumentParser(description="Generate the CSV data for the tables and figures.")
    ap.add_argument("--output", type=Path, default=Path("data/publication"))
    ap.add_argument("--reuse-results", type=Path, help="copy an earlier timing run instead of re-timing")
    ap.add_argument("--sizes", default=",".join(map(str, SIZES)))
    ap.add_argument("--sessions", type=int, default=3)
    ap.add_argument("--repeats", type=int, default=9)
    ap.add_argument("--warmup", type=int, default=3)
    ap.add_argument("--target-batch-seconds", type=float, default=0.05)
    ap.add_argument("--quick", action="store_true", help="short run at n = 10, 50, 100")
    args = ap.parse_args()

    sizes = (10, 50, 100) if args.quick else tuple(int(x) for x in args.sizes.split(","))
    if 4 in sizes:
        ap.error("n = 4 is singular and cannot be timed")
    if args.repeats < 3:
        ap.error("--repeats must be at least 3")

    out = args.output
    out.mkdir(parents=True, exist_ok=True)
    self_test()
    print("self-test passed")

    if args.reuse_results:
        timing, accuracy, meta = reuse(args.reuse_results, out)
        source = f"reused: {args.reuse_results.resolve()}"
    else:
        timing, accuracy, meta = run_benchmark(sizes, args.repeats, args.warmup,
                                               args.target_batch_seconds, args.sessions, out)
        source = "new benchmark run"

    write_tables(timing, accuracy, meta, source, out)
    print(f"done, CSV files in {out.resolve()}")


if __name__ == "__main__":
    main()
